#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-accessibility-wiring.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-accessibility-wiring — refuses a Storybook UI repo that does not wire
 * the axe a11y gate the ACCESSIBILITY standard names (ACCESSIBILITY.yaml.test_runner).
 *
 * The gap this closes: ACCESSIBILITY.yaml advertises `pnpm verify:stories`
 * (test-storybook + axe-core, config at .storybook/test-runner.ts) as THE
 * accessibility gate — but nothing checked that a UI repo actually wires it.
 * A repo could ship components with real WCAG violations while every other
 * design-system gate stayed green, because the a11y gate simply was not there.
 *
 * What it checks — for every `.storybook/` package in the repo:
 *   1. `.storybook/test-runner.ts` exists (the axe injection config),
 *   2. package.json declares `test:stories` AND `verify:stories` scripts,
 *   3. the a11y gate is chained into verify — some `verify` script (this
 *      package's or the repo root's) references `verify:stories`.
 *
 * Scope / honesty: this is a WIRING gate. It proves the axe gate EXISTS and is
 * part of the verify chain; the actual axe rule-run happens inside
 * `verify:stories` (which this confirms is wired). It does not itself launch
 * Chromium.
 *
 * No-op green when: `.standards/autonomy.yaml` declares `ui_discipline: none`,
 * or the repo has no `.storybook/` (no Storybook UI to gate).
 *
 * Usage: node scripts/verify/verify-accessibility-wiring.mjs [<repo-root>]
 * Exits 0 when every Storybook package wires the a11y gate (or none apply); 1 otherwise.
 */
import { readdirSync, readFileSync, existsSync } from "node:fs";
import { join, relative, dirname } from "node:path";

const REPO_ROOT = process.argv[2] || process.cwd();
const NAME = "verify-accessibility-wiring";
const IGNORE = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "out", "coverage", ".vercel"]);

// ui_discipline: none → this standard short-circuits (per CLAUDE.md project-type gate).
try {
  const autonomy = readFileSync(join(REPO_ROOT, ".standards", "autonomy.yaml"), "utf8");
  if (/\bui_discipline\s*:\s*none\b/.test(autonomy)) {
    process.stdout.write(`✅ ${NAME} — ui_discipline: none; n/a.\n`);
    process.exit(0);
  }
} catch { /* no autonomy file → assume UI may apply, continue */ }

function findStorybookDirs(dir, acc = []) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return acc; }
  for (const e of entries) {
    if (IGNORE.has(e.name)) continue;
    const p = join(dir, e.name);
    if (!e.isDirectory()) continue;
    if (e.name === ".storybook") acc.push(p);
    else findStorybookDirs(p, acc);
  }
  return acc;
}

function readJson(file) {
  try { return JSON.parse(readFileSync(file, "utf8")); } catch { return null; }
}

const rootPkg = readJson(join(REPO_ROOT, "package.json")) || {};
const rootVerify = String(rootPkg.scripts?.verify || "");

const sbDirs = findStorybookDirs(REPO_ROOT);
if (sbDirs.length === 0) {
  process.stdout.write(`✅ ${NAME} — no Storybook UI in this repo; nothing to gate.\n`);
  process.exit(0);
}

const violations = [];
for (const sb of sbDirs) {
  const pkgRoot = dirname(sb);
  const rel = relative(REPO_ROOT, pkgRoot) || ".";
  if (!existsSync(join(sb, "test-runner.ts"))) {
    violations.push(`${rel}: missing .storybook/test-runner.ts (the axe-core injection config)`);
  }
  const pkg = readJson(join(pkgRoot, "package.json")) || {};
  const scripts = pkg.scripts || {};
  if (!scripts["test:stories"]) violations.push(`${rel}: package.json has no "test:stories" script`);
  if (!scripts["verify:stories"]) violations.push(`${rel}: package.json has no "verify:stories" script`);
  const pkgVerify = String(scripts.verify || "");
  const chained = /verify:stories/.test(pkgVerify) || /verify:stories/.test(rootVerify);
  if (!chained) {
    violations.push(`${rel}: "verify:stories" is not chained into any verify script (ACCESSIBILITY: the a11y gate must be part of \`pnpm verify\`)`);
  }
}

if (violations.length === 0) {
  process.stdout.write(`✅ ${NAME} — ${sbDirs.length} Storybook package(s) wire the axe a11y gate.\n`);
  process.exit(0);
}
process.stderr.write(`\n❌ ${NAME}: ${violations.length} a11y-wiring violation(s)\n`);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(`\n   Fix: add .storybook/test-runner.ts + test:stories/verify:stories scripts and chain verify:stories into pnpm verify. ACCESSIBILITY.yaml.test_runner.\n`);
process.exit(1);
